type Entity = "order" | "payment" | "stock" | "refund";
type Action = "created" | "updated" | "deleted";
type EventName = `${Entity}.${Action}`;

type OrderHandlers = {
  [N in keyof OrderEvents as HandlerName<N>]?: (payload: OrderEvents[N]) => void;
};

const handlers = new Map<string, (() => void)[]>();

function on(name: string, handler: () => void): void {
  handlers.set(name, [...(handlers.get(name) ?? []), handler]);
}

function emit(name: string): number {
  const list = handlers.get(name) ?? [];
  for (const handler of list) handler();
  return list.length;
}

on("order.paid", () => console.log("receipt sent"));
on("order.payed", () => console.log("loyalty points added"));
console.log(emit("order.paid"), emit("order.refunded"));

function capitalize<S extends string>(text: S): Capitalize<S> {
  return (text.charAt(0).toUpperCase() + text.slice(1)) as Capitalize<S>;
}

const names = ["paid", "shipped", ""].map((status) => `on${capitalize(status)}`);
