function splitName(name: string): [string, string] {
  const dot = name.indexOf(".");
  return dot === -1 ? [name, ""] : [name.slice(0, dot), name.slice(dot + 1)];
}

console.log(splitName("order.item.added"), splitName("heartbeat"));

function matches(pattern: string, name: string): boolean {
  if (pattern === "*") return true;
  if (pattern.endsWith(".*")) return name.startsWith(pattern.slice(0, -1));
  return pattern === name;
}

console.log(matches("order.*", "order.paid"), matches("order.*", "orders.archived"), matches("order.*", "order"));

type Permission = `${"orders" | "refunds"}:${"read" | "approve"}`;
type Grant = Permission | `${"orders" | "refunds"}:*` | "*";

function can(grants: readonly Grant[], needed: Permission): boolean {
  const [resource] = needed.split(":");
  return grants.some((grant) => grant === "*" || grant === needed || grant === `${resource}:*`);
}

const cashier: Grant[] = ["orders:read", "refunds:read"];
const supervisor: Grant[] = ["orders:*", "refunds:read"];
console.log(can(cashier, "refunds:approve"), can(supervisor, "orders:approve"), can(supervisor, "refunds:approve"));

function matchRoute(path: string, url: string): Record<string, string> | null {
  const pattern = path.split("/");
  const parts = url.split("/");
  if (parts.length !== pattern.length) return null;
  const params: Record<string, string> = {};
  for (let i = 0; i < pattern.length; i++) {
    if (pattern[i].startsWith(":")) params[pattern[i].slice(1)] = decodeURIComponent(parts[i]);
    else if (pattern[i] !== parts[i]) return null;
  }
  return params;
}

