const subscriptions: { pattern: string; label: string }[] = [
  { pattern: "order.*", label: "audit" },
  { pattern: "order.shipped", label: "sms" },
  { pattern: "*", label: "metrics" },
  { pattern: "stock.*", label: "restock" },
];

function targets(name: string): string[] {
  return subscriptions
    .filter(({ pattern }) => pattern === "*" || pattern === name || (pattern.endsWith(".*") && name.startsWith(pattern.slice(0, -1))))
    .map(({ label }) => label);
}

